"""Build non-PBMS screen guidance and deterministic routes from installed UI sources."""
from pathlib import Path
import json,re
root=Path(__file__).resolve().parent
guides=[];routes=[]
def add(module,stage,pattern,purpose,steps,requirements,next_step,issues):
 guides.append(dict(slug='nsipa-screen-'+module+'-'+re.sub('[^a-z0-9]+','-',stage.lower()).strip('-'),module=module,stage=stage,audience='all',title=stage,purpose=purpose,steps=steps,requirements=requirements,next_step=next_step,issues=issues,scope='local_workflow',visibility='public'))
 if pattern:routes.append(dict(module=module,pattern=pattern,stage=stage))
access='An account authorised for this service and the correct record or task reference.'
errors='Check the selected record and any active filters. Resolve the displayed validation message before retrying. If access is denied, contact the service administrator; choosing another help role does not change your permissions.'
add('platform','Sign in',None,'Use your existing NSIPA account to access the requested service.','Check the service address and choose the sign-in method shown on the page.\nEnter your account details and submit the sign-in form.\nWait for the service to open. If an error appears after sign-in, retain the service name and error message for the administrator; never share your password.','An active account for the relevant staff or beneficiary service.','Confirm that the requested service and your own account are shown before continuing.','A successful identity sign-in does not grant access to every service. A callback error or repeated redirect needs administrator investigation; do not create duplicate accounts to resolve it.')
add('beneficiary','Profile details',r'/myprofile(?:/|$)','Review the personal details used by the beneficiary portal.','Open your profile and check that it belongs to you.\nReview the displayed contact and identifying information.\nUse the available edit controls for supported corrections and confirm the saved result.',access,'Return to the programme or application that needs the corrected information.',errors)
add('beneficiary','Payment account details',r'/accounts(?:/|$)','Review the payment account information linked through the available account service.','Open Accounts and select the relevant account or mapper.\nCheck the account identity and any verification status shown before entering a correction.\nSubmit only the changes requested by the form and confirm the returned status. Do not put full account credentials in help or complaint text.',access,'Check the account status before proceeding with a programme application or payment enquiry.','An account link does not itself confirm enrollment or settlement. If linking fails, record the displayed error and contact the authorised support team.')
add('beneficiary','Benefit history',r'/benefits(?:/|$)','Review the benefits displayed for your registered programmes.','Select the relevant benefit or programme.\nCheck the period, amount or quantity and the recorded status.\nOpen available details to distinguish an entitlement from a completed payment.',access,'Use the application or enquiry workflow if a displayed benefit needs clarification.','A listed benefit is not proof that funds have reached an account. Use the recorded payment status and authorised support process to investigate discrepancies.')
add('beneficiary','Complaints and enquiries',r'/complaints(?:/|$)','Raise or follow an enquiry about your registration, application or benefit.','Check whether an enquiry already exists for the issue.\nDescribe the issue using the relevant application or programme reference and provide only the information requested.\nSubmit the enquiry and retain its reference so you can follow the response.',access,'Track the enquiry status and respond to requests for additional information.','Do not include passwords or unnecessary financial information. An enquiry does not change eligibility or guarantee payment.')
add('beneficiary','Notifications',r'/notifications(?:/|$)','Read service messages and identify any action needed on your application.','Open the notification and check the referenced programme or application.\nRead the complete message and any due date shown.\nUse the linked service screen to complete the requested action, then check its status.',access,'Return to the related application to confirm the outcome.','Do not treat a message preview as the full instruction. Open the notification before acting and verify unexpected requests with the service administrator.')
add('beneficiary','News and announcements',r'/news(?:/|$)','Read programme announcements without confusing them with an individual application decision.','Open the announcement and check its date and programme.\nRead the full eligibility or application information provided.\nUse the programme screen to check whether an application is available to your account.','Access to the beneficiary portal.','Track your own application separately from public announcements.','An announcement does not confirm that you are enrolled or entitled to a benefit.')
add('beneficiary','Beneficiary dashboard',r'/dashboard(?:/|$)','Understand the summary of your registrations, applications and benefits.','Review the summary labels and any active period filter.\nOpen the relevant application or benefit for its detailed status.\nRespond to requested corrections using the related workflow.',access,'Use the detailed record when you need to confirm a decision or payment status.','Summary counts can cover different stages. Do not interpret an application count as an approval or a benefit count as settlement.')
add('register','Registry configuration',r'/configuration/(?:registry|registers|data-models|intake-forms)(?:/|$)','Maintain the registry definitions and forms available to authorised configuration staff.','Identify the registry, register, data model or intake form being configured.\nReview field definitions, required values, labels and existing dependencies before editing.\nSave only authorised changes and check the affected form or record screen before using the new configuration.','Registry configuration permission and an agreed definition of the intended change.','Verify the resulting fields and validation behaviour in the affected registration workflow.','Changing a label does not migrate stored data. If a change affects existing fields or records, follow the registry administrator’s change process before proceeding.')
add('register','Sharing and approval configuration',r'/configuration/(?:data-policies|awe-policy-config)(?:/|$)','Review the policies that control registry sharing and approval routing.','Open the intended policy or workflow mapping.\nCheck its scope, applicable records, decision stages and permitted recipients.\nSave authorised changes and confirm the selected policy and status.','Permission to administer registry policies and the agreed policy requirements.','Check the affected request workflow using an authorised test record.','Do not broaden data access to resolve an unrelated form error. A policy shown in configuration must also be valid for the applicable workflow.')
add('register','Outgoing message monitoring',r'/outgoing-messages(?:/|$)','Inspect outgoing registry messages and identify delivery failures.','Find the message associated with the correct record or request.\nCheck its destination, event and processing status.\nReview the displayed error before using any authorised retry or correction action.',access,'Confirm the resulting delivery status and retain the message reference for unresolved failures.','A queued message is not confirmed receipt by the destination. Avoid repeated retries until the cause of a failure is understood.')
add('register','Outgoing integration configuration',r'/configuration/outgest-configurations(?:/|$)','Maintain the configured topics and templates for outgoing registry integration.','Select the intended topic or template.\nCheck its field mappings, destination and expected record type.\nSave authorised changes and verify an approved test message before relying on the integration.','Integration configuration permission and the approved destination schema.','Inspect outgoing message status for the configured integration.','A template change can affect future messages. Confirm dependencies and avoid using live personal data in troubleshooting examples.')
add('register','Registry profile',r'/myprofile(?:/|$)','Check the staff profile associated with the current registry session.','Confirm that the account shown is your own.\nReview the available profile information and permitted update controls.\nContact the access administrator if the identity or assigned access is incorrect.',access,'Return to the registry task once the account details are correct.','Profile changes do not automatically grant new registry permissions.')
add('awe','Approval simulation',r'/policies/[^/]+/versions/[^/]+/simulate(?:/|$)','Test how a policy version routes a supplied example request.','Confirm the policy and version selected for simulation.\nEnter a fictional example that matches the expected request structure.\nRun the simulation and inspect the resolved stages and approvers.','Policy access and a synthetic test request without personal or confidential data.','Compare the simulated routing with the intended approval design before any policy activation.','Simulation does not approve a live request. A successful example does not prove that every production input resolves correctly.')
add('awe','Approval delegation',r'/delegations(?:/|$)','Review delegation settings that affect who can act on approval tasks.','Identify the delegating user and intended substitute.\nCheck the permitted scope and effective dates shown by the form.\nSave only an authorised delegation and confirm its resulting status.','Permission to administer delegations and the agreed delegation scope.','Check the affected task assignment after the delegation becomes effective.','Delegation must not be used to avoid independent-review requirements. Check the effective period before assuming a substitute can act.')
add('awe','Webhook deliveries',r'/deliveries(?:/|$)','Follow delivery of approval events to configured receiving services.','Locate the delivery associated with the relevant approval request.\nReview its destination, attempt status and response or error.\nUse an available retry only after checking the cause and confirming that the receiving service can safely handle it.',access,'Confirm the final delivery status separately from the approval decision.','An approved request may still have a failed delivery. Repeated delivery is not a new approval and must not be treated as a duplicate decision.')
add('awe','Approval audit log',r'/audit(?:/|$)','Inspect recorded approval events to understand the sequence of actions.','Filter the log to the relevant request, policy or actor.\nRead timestamps, action names and related identifiers in sequence.\nOpen the related request to confirm its current state.',access,'Use the event references when asking the approval administrator to investigate a discrepancy.','An audit event records an action at a point in time; it may not describe the current request state. Avoid including unrelated personal information in exported evidence.')
# Explicit local portal routes that previously fell through to household registration.
for stage,pattern,purpose,steps in [
 ('Programme analytics',r'^/registration/(analytics|dashboard)(?:/|$)','Review the registration and programme measures available to your staff account.','Check the reporting period and scope.\nApply the available filters and inspect the chart labels and counts.\nOpen the underlying workflow when you need to confirm an individual status.'),
 ('Partner simulation',r'^/registration/simulation(?:/|$)','Explore a synthetic integration journey and inspect its recorded outcomes.','Read the scenario and confirm that all inputs are fictional.\nOpen an existing run to inspect the recorded steps and outcomes.\nIf authorised to start a demonstration, review its inputs first and inspect the resulting report afterward.'),
 ('Mobile collection setup',r'^/(registration/mobile|field-preview)(?:/|$)','Choose the available mobile collection application or web preview.','Read the installation or preview instructions for your device.\nUse the supplied demonstration with fictional information.\nCheck the documented synchronisation and submission behaviour before relying on a collected record.'),
 ('Sandbox readiness',r'^/registration/phase1/readiness(?:/|$)','Inspect the evidence of which demonstration capabilities are available.','Read each capability and its reported status.\nOpen any linked evidence and check its scope and date.\nDistinguish demonstrated behaviour from integrations that still require configuration.'),
 ('Sandbox grievances',r'^/registration/phase1/grievances(?:/|$)','Review or record a fictional grievance in the demonstration workflow.','Locate the case or open the available new-case form.\nDescribe the fictional issue and follow the displayed status controls.\nConfirm the recorded case reference and resulting status.'),
 ('Sandbox conditionality',r'^/registration/phase1/conditionality(?:/|$)','Inspect the demonstration checks associated with programme conditions.','Select the fictional programme or household record.\nReview the condition, observation and result displayed.\nRecord only permitted demonstration changes and confirm the resulting status.'),
 ('Sandbox field collection',r'^/registration/phase1/field(?:/|$)','Use the demonstration field workflow to capture a fictional collection record.','Choose the relevant form or existing record.\nEnter fictional information and resolve validation errors.\nSubmit through the displayed workflow and confirm its recorded status.'),
 ('Sandbox content management',r'^/registration/phase1/cms(?:/|$)','Manage the demonstration content available to authorised staff.','Open the relevant content item.\nReview its title, complete text and intended audience before editing.\nSave or publish only through the controls available to your account and confirm the result.'),
 ('Sandbox portal',r'^/registration/phase1(?:/|$)','Navigate the NSIPA demonstration features and understand their limits.','Choose the demonstration feature needed for your task.\nRead the screen instructions and use only fictional records.\nInspect the resulting status or report without treating it as a live eligibility or payment decision.'),
 ('Territorial intelligence',r'^/territories(?:/|$)','Explore geographic indicators together with their stated sources and reporting periods.','Select the administrative area and indicator.\nRead the source, reporting year and coverage notes before comparing values.\nUse the map or detail view to inspect the selected area without interpreting an indicator as a household eligibility decision.'),
 ('Jos pilot demonstration',r'^/(jos-cct|registration/jos)(?:/|$)','Explore the proposed pilot using the explicitly fictional demonstration records.','Choose a dashboard or journey step.\nReview the assumptions, measures and simulation labels.\nInspect the demonstration outcome without treating it as an authorised allocation or real payment.')]:
 add('platform',stage,pattern,purpose,steps,'An account with the required screen permission, where sign-in is requested. Use fictional information for sandbox and demonstration screens.','Review the resulting screen or report and follow the next action that is actually available.','Demonstration results are not proof of a live integration, eligibility decision or transferred funds. If the screen is unavailable, report the service address and displayed error to the administrator.')
# Routes for established guides; these are more reliable than incidental heading keywords.
for module,pattern,stage in [
 ('odk',r'/projects/[^/]+/forms/[^/]+/submissions','Submit and quality check'),('odk',r'/projects','Prepare collection form'),
 ('master-data-ui',r'/(geograph|location|administrative)','Location reference data'),('master-data-ui',r'/(attribute|code-list|dataset)','Maintain shared attributes'),
 ('partner-management',r'/(partner|organisation)','Partner onboarding'),('partner-management',r'/(key|integration|credential)','Integration access'),
 ('consent-manager',r'/(polic)','Partner policy scope'),('consent-manager',r'/(consent|request)','Review consent'),
 ('iam-staff-ui',r'/(role|permission)','Role assignment'),('iam-staff-ui',r'/(user|account|staff)','Account management'),('iam-staff-ui',r'/(application|login-provider)','Application and login provider configuration')]:routes.append(dict(module=module,pattern=pattern,stage=stage))
(root/'other-module-guidance.json').write_text(json.dumps({'guides':guides,'routes':routes},ensure_ascii=False,indent=2))
p=root/'context.js';s=p.read_text()
insert=" const screenRoutes="+json.dumps(routes,separators=(',',':'))+";\n"
s=s.replace(' function resolveBase(s={}){',insert+' function resolveBase(s={}){')
needle="  if(!hosts[host]){"
s=s.replace(needle,"  if(host==='keycloak'||/(?:^|\\/)(?:login|signin|sign-in)(?:\\/|$)/.test(path))return use('platform','Sign in','screen route');\n  const mappedScreen=screenRoutes.find(r=>r.module===mod&&new RegExp(r.pattern,'i').test(path));\n  if(mappedScreen)return use(mappedScreen.module,mappedScreen.stage,'screen route');\n"+needle)
s=s.replace("if(!s.explicit?.stage){","if(!s.explicit?.stage&&initial.source!=='screen route'){")
p.write_text(s)
p=root/'help.js';s=p.read_text();s=s.replace("||/^(keycloak\\.|g2p-keycloak\\.)/.test(location.hostname)",'');p.write_text(s)
print(json.dumps({'new_guides':len(guides),'route_rules':len(routes)}))
